/**
 * Virtual module produced by `react-native-dotenv` from `mobile/.env`.
 * `allowUndefined: true` in babel.config.js means every key is optional.
 */
declare module '@env' {
  /** Overrides the inferred backend base URL, e.g. http://192.168.1.20:8000 */
  export const API_URL: string | undefined;
}
